import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;

public class SecureDeserializer {
    // A whitelist of allowed classes to prevent deserialization attacks
    private static final Set<String> ALLOWED_CLASSES = Set.of("java.lang.String", "java.lang.Integer");

    // Custom ObjectInputStream that implements a "Look-ahead" pattern
    public static class ValidatingObjectInputStream extends ObjectInputStream {
        public ValidatingObjectInputStream(InputStream in) throws IOException {
            super(in);
        }

        @Override
        protected Class<?> resolveClass(ObjectStreamClass desc) throws IOException, ClassNotFoundException {
            // Check if the incoming class is in our safe whitelist
            if (!ALLOWED_CLASSES.contains(desc.getName())) {
                throw new InvalidClassException("Unauthorized deserialization attempt", desc.getName());
            }
            return super.resolveClass(desc);
        }
    }

    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(8081);
        System.out.println("Secure server listening on port 8081...");

        while (true) {
            try (Socket socket = serverSocket.accept();
                 // Use the validating stream instead of the standard ObjectInputStream
                 ValidatingObjectInputStream vois = new ValidatingObjectInputStream(socket.getInputStream())) {

                Object obj = vois.readObject();
                System.out.println("Received safely: " + obj.toString());
            } catch (ClassNotFoundException | InvalidClassException e) {
                System.err.println("Security Alert: Blocked attempt to deserialize unauthorized class!");
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

